import type { ReactNode } from 'react'
import { Link } from 'react-router-dom'
import SharkArt from './Sharks'
import { POD_HEX } from './PodShark'
import { dayLabel, pct, reasonLabel, tone, usd } from './format'
import type { PitchView, PodView, SessionView } from './replay'
import { spotlightFor } from './replay'
import type { Pod, Snapshot } from './types'

// What each strategy does, in plain words. These describe the code in the_reef/strategy; they are not generated by a model.
const HOW: Record<string, { verb: string; rule: string }> = {
  momentum: {
    verb: 'Chases breakouts',
    rule: 'Buys a close above the 20-day high while the stock is above its 50-day average, then trails its stop up as the trend runs.',
  },
  contrarian: {
    verb: 'Buys the dip',
    rule: 'Waits for a stock in an uptrend to fall unusually far (z-score below -1.7), buys it with a fixed stop, and sells when the price recovers to its 20-day average.',
  },
}

const Label = ({ children }: { children: ReactNode }) => <div className="text-[10px] uppercase tracking-[0.14em] text-slate-500">{children}</div>

function stateChip(p: PitchView) {
  if (!p.decision) return <span className="chip chip-neutral">PENDING</span>
  if (p.state === 'DECLINED') return <span className="chip chip-declined">DECLINED</span>
  if (p.state === 'NOT_FILLED') return <span className="chip chip-declined">NOT FILLED</span>
  return <span className="chip chip-funded">FUNDED</span>
}

export function Contender({ pod, pv, rival, view, pitchOf, onSelect }:
  { pod: Pod; pv: PodView; rival: PodView | undefined; view: SessionView; pitchOf: (symbol: string, pod: string) => PitchView | undefined; onSelect: (id: string) => void }) {
  const hex = POD_HEX[pod.pod_id]
  const how = HOW[pod.pod_id]
  const species = pod.pod_id === 'momentum' ? 'mako' : 'hammerhead'
  const todays = view.today.filter(p => p.pod_id === pod.pod_id)
  const boughtToday = pv.positions.some(x => x.sessions_held === 0)
  const lead = rival ? (pv.return - rival.return) * 100 : 0
  const status = boughtToday ? 'Just bought in'
    : todays.some(p => p.decision?.outcome === 'FUNDED') ? 'Pitch funded, order queued'
    : pv.positions.length ? `Holding ${pv.positions.length}`
    : 'Waiting for a setup'
  return (
    <div className="contender p-4" style={{ borderColor: `${hex}44` }}>
      <div className="flex items-center justify-between gap-2">
        <Link to={`/team/${pod.pod_id}`} className="text-xl font-bold hover:underline" style={{ color: hex }}>{pod.name}</Link>
        {rival && view.index >= 1 && (
          <span className={`chip ${pv.lead_by_return ? 'chip-funded' : 'chip-neutral'}`}>
            {pv.lead_by_return ? `LEADS BY ${Math.abs(lead).toFixed(2)} PTS` : lead === 0 ? 'LEVEL' : `TRAILS BY ${Math.abs(lead).toFixed(2)} PTS`}
          </span>
        )}
      </div>
      <p className="text-sm font-semibold text-slate-200">{how.verb}</p>

      <div className="relative -mx-2 mt-1 flex justify-center">
        <SharkArt species={species} size={230} charging={species === 'mako' && boughtToday} />
      </div>

      <div className="mt-1 grid grid-cols-2 gap-2">
        <div><Label>Sleeve NAV</Label><div className="font-mono text-2xl font-bold text-white">{usd(pv.nav)}</div></div>
        <div className="text-right"><Label>Return on {usd(pv.funded)}</Label><div className={`font-mono text-2xl font-bold ${tone(pv.return)}`}>{pct(pv.return, 2)}</div></div>
      </div>

      <div className="mt-3 rounded-lg bg-slate-950/50 p-2.5">
        <Label>Right now</Label>
        <div className="text-sm font-semibold text-slate-100">{status}</div>
        {pv.positions.length > 0 && (
          <div className="mt-1.5 flex flex-wrap gap-1.5">
            {pv.positions.map(x => {
              const pitch = pitchOf(x.symbol, pod.pod_id)
              return (
                <button key={x.symbol} onClick={() => pitch && onSelect(pitch.proposal_id)}
                        className="chip hover:brightness-125" style={{ color: hex, background: `${hex}1a`, borderColor: `${hex}55` }}
                        title={`${x.shares} shares at ${usd(x.avg_cost)}, stop ${usd(x.stop)}; click for the pitch`}>
                  {x.symbol} {x.shares} sh <span className={tone(x.unrealized)}>{usd(x.unrealized, true)}</span>
                </button>
              )
            })}
          </div>
        )}
      </div>

      <dl className="mt-3 grid grid-cols-3 gap-1 text-center">
        <div><Label>Exposure</Label><dd className="font-mono text-sm text-slate-100">{view.index === 0 ? '-' : pct(pv.avg_exposure, 0, false)}</dd></div>
        <div><Label>Avg hold</Label><dd className="font-mono text-sm text-slate-100">{pv.avg_hold === null ? '-' : `${pv.avg_hold.toFixed(0)} sessions`}</dd></div>
        <div><Label>Win rate</Label><dd className="font-mono text-sm text-slate-100">{pv.win_rate === null ? '-' : `${(pv.win_rate * 100).toFixed(0)}% of ${pv.trades}`}</dd></div>
      </dl>
      <p className="mt-2 text-center text-xs text-slate-400">Exits so far: {pv.stop_exits} by stop, {pv.rule_exits} by its own rule</p>
      <p className="mt-3 text-xs leading-snug text-slate-400">{how.rule}</p>
    </div>
  )
}

function Rail({ n, title, children, dim }: { n: number; title: string; children?: ReactNode; dim?: boolean }) {
  return (
    <li className={`relative pl-8 ${dim ? 'opacity-45' : ''}`}>
      <span className="absolute left-0 top-0.5 grid h-5 w-5 place-items-center rounded-full border border-slate-500 bg-slate-950 font-mono text-[10px] text-slate-300">{n}</span>
      <div className="text-[13px] font-semibold text-slate-100">{title}</div>
      {children && <div className="text-xs leading-snug text-slate-400">{children}</div>}
    </li>
  )
}

export function Spotlight({ pitch, fresh, view, pod, others, onSelect }:
  { pitch: PitchView; fresh: boolean; view: SessionView; pod: Pod; others: PitchView[]; onSelect: (id: string) => void }) {
  const hex = POD_HEX[pitch.pod_id]
  const d = pitch.decision
  const pk = pitch.packet
  const funded = d?.outcome === 'FUNDED'
  const ago = view.index - (view.pitches.length ? sessionIndexOf(view, pitch) : 0)
  return (
    <div className="rounded-2xl border bg-slate-950/70 p-4" style={{ borderColor: funded ? 'rgba(0,255,136,0.4)' : 'rgba(255,68,68,0.35)', boxShadow: `0 0 0 1px ${hex}22, 0 10px 40px rgba(0,0,0,0.35)` }}>
      <div className="flex flex-wrap items-center gap-2">
        <span className="text-[10px] font-bold uppercase tracking-[0.18em] text-amber-300">Apex's decision</span>
        <span className="text-xs text-slate-400">{fresh ? `decided at the close of ${dayLabel(view.day)}` : `last decision, ${ago} session${ago === 1 ? '' : 's'} ago (${dayLabel(pitch.as_of_session)})`}</span>
      </div>

      <div className="mt-2 flex flex-wrap items-center gap-2">
        <span className="chip" style={{ color: hex, background: `${hex}1a`, borderColor: `${hex}55` }}>{pod.name} pitches</span>
        <span className="font-mono text-2xl font-bold text-white">{pitch.symbol}</span>
        {stateChip(pitch)}
      </div>
      <blockquote className="mt-2 border-l-2 pl-3 text-sm text-slate-200" style={{ borderColor: hex }}>{pk.thesis}</blockquote>

      <ol className="mt-3 space-y-2.5">
        <Rail n={1} title={`Asked for ${pk.capital_request.shares} shares (${usd(pk.capital_request.dollars)})`}>
          {Math.round(Number(pk.capital_request.fraction_of_sleeve_cash) * 100)}% of its sleeve's cash. Stop {usd(pk.exit_plan.stop_price)} ({pk.risk.stop_distance_pct}% away), {usd(pk.risk.risk_at_request)} at risk.
        </Rail>
        {d && (funded ? (
          <Rail n={2} title={`Apex funded it: up to ${d.granted_shares} shares`}>
            Ranked #{d.rank} of {d.of} from {pod.name}. The D0 ceiling was {d.ceiling_shares} shares; Apex never grants more than a pod asks for. Risk Engine pre-check passed ({d.risk_check_shares} sh).
          </Rail>
        ) : (
          <Rail n={2} title={`Apex declined: ${reasonLabel(d.reasons)}`}>
            {pitch.decision_explained.length ? pitch.decision_explained.join(' ') : d.detail}
          </Rail>
        ))}
        {funded && pitch.state === 'QUEUED' && (
          <Rail n={3} title={`Order queued for ${dayLabel(d!.fill_session ?? '')}'s open`}>No price is assumed in advance. The fill is not known yet.</Rail>
        )}
        {funded && pitch.state === 'NOT_FILLED' && <Rail n={3} title="The order did not fill">It was refused at the open. Nothing was bought.</Rail>}
        {pitch.entry && (
          <Rail n={3} title={`Bought ${pitch.entry.shares} at ${usd(pitch.entry.price)} on ${dayLabel(pitch.entry.session_day)}`}>
            Risk sized the fill from the actual open. {pitch.state === 'OPEN' && <>Stop now {usd(pitch.stop)}.</>}
          </Rail>
        )}
        {pitch.state === 'OPEN' && (
          <Rail n={4} title={`Open: ${usd(pitch.pnl, true)} (${pct(pitch.position_return, 1)}) at ${dayLabel(view.day)}'s close`}>
            {pitch.sessions_held} session{pitch.sessions_held === 1 ? '' : 's'} held. No outcome yet.
          </Rail>
        )}
        {pitch.state === 'CLOSED' && pitch.exit && (
          <Rail n={4} title={`Sold at ${usd(pitch.exit.price)} on ${dayLabel(pitch.exit.session_day)}: ${usd(pitch.pnl, true)} (${pct(pitch.position_return, 1)})`}>
            {pitch.exit.reason}. Held {pitch.sessions_held} sessions.
          </Rail>
        )}
        {!funded && d && <Rail n={3} title="Nothing was traded" dim>No order, no fill, no effect on any sleeve.</Rail>}
      </ol>

      <div className="mt-3 flex flex-wrap items-center gap-2 border-t border-slate-800 pt-3 text-xs">
        <Link to={`/proposal/${encodeURIComponent(pitch.proposal_id)}`} className="rounded-full border border-cyan-300/50 bg-cyan-400/10 px-3 py-1.5 font-semibold text-cyan-100 hover:bg-cyan-400/20">
          Follow the full story
        </Link>
        {d && <Link to={`/lab?seq=${d.seq}`} className="rounded-full border border-slate-600 px-3 py-1.5 text-slate-200 hover:border-cyan-300/60">Evidence: ledger #{d.seq}</Link>}
        {pitch.entry && <Link to={`/lab?seq=${pitch.entry.seq}`} className="rounded-full border border-slate-600 px-3 py-1.5 text-slate-200 hover:border-cyan-300/60">Fill: ledger #{pitch.entry.seq}</Link>}
        {pitch.exit && <Link to={`/lab?seq=${pitch.exit.seq}`} className="rounded-full border border-slate-600 px-3 py-1.5 text-slate-200 hover:border-cyan-300/60">Exit: ledger #{pitch.exit.seq}</Link>}
      </div>
      {view.index < view.total - 1 && <p className="mt-2 text-[11px] text-slate-500">The full story page shows the whole record, including what happened after this session.</p>}

      {others.length > 0 && (
        <div className="mt-3 flex flex-wrap items-center gap-1.5 text-xs text-slate-400">
          Also decided today:
          {others.map(o => (
            <button key={o.proposal_id} onClick={() => onSelect(o.proposal_id)} className="chip hover:brightness-125"
                    style={{ color: POD_HEX[o.pod_id], background: `${POD_HEX[o.pod_id]}14`, borderColor: `${POD_HEX[o.pod_id]}55` }}>
              {o.symbol} {o.decision?.outcome === 'FUNDED' ? 'funded' : 'declined'}
            </button>
          ))}
        </div>
      )}
    </div>
  )
}

function sessionIndexOf(view: SessionView, pitch: PitchView): number {
  // Sessions between the pitch and the viewed session, by the fund NAV series (one entry per session).
  const i = view.fundSeries.findIndex(([d]) => d === pitch.as_of_session)
  return i < 0 ? view.index : i
}

export function ApexColumn({ snap, view, selected, onSelect }: { snap: Snapshot; view: SessionView; selected: string | null; onSelect: (id: string) => void }) {
  const auto = spotlightFor(view)
  const chosen = selected ? view.pitches.find(p => p.proposal_id === selected) : undefined
  const pitch = chosen ?? auto?.pitch
  const fresh = chosen ? chosen.decided_today : !!auto?.fresh
  const pod = pitch ? snap.pods.find(p => p.pod_id === pitch.pod_id)! : undefined
  const active = snap.pods.filter(p => p.status === 'ACTIVE')
  const others = view.today.filter(o => o.proposal_id !== pitch?.proposal_id && !(o.decision?.outcome === 'DECLINED' && !o.decision.reasons.includes('D0_RANK_CAP')))
  const bench = view.benchReturn
  return (
    <div className="flex flex-col items-center">
      <div className="relative flex w-full flex-col items-center">
        <SharkArt species="greatwhite" size={200} />
        <div className="-mt-1 text-center">
          <div className="inline-flex items-center gap-2 rounded-full border border-amber-300/60 bg-amber-300/10 px-4 py-1">
            <span className="text-lg font-extrabold tracking-[0.2em] text-amber-200">APEX</span>
            <span className="text-xs uppercase tracking-[0.14em] text-amber-100/80">Chief Investment Officer</span>
          </div>
          <p className="mx-auto mt-1.5 max-w-md text-xs leading-snug text-slate-400">
            Funds pitches, not sharks. Sleeves are fixed ({active.map(p => `${p.name} ${Number(p.sleeve_weight) * 100}%`).join(', ')}, {Number(snap.apex.unallocated_weight) * 100}% cash).
            Fixed rules, no language model.
          </p>
          <p className="mt-1 font-mono text-xs text-slate-300">
            Fund {usd(view.fundNav)} <span className={tone(view.fundReturn)}>{pct(view.fundReturn, 2)}</span>
            {bench !== null && <span className="text-slate-500"> · holding the whole universe {pct(bench, 2)}</span>}
          </p>
        </div>
      </div>
      <div className="mt-3 w-full">
        {pitch && pod
          ? <Spotlight pitch={pitch} fresh={fresh} view={view} pod={pod} others={others} onSelect={onSelect} />
          : <div className="rounded-2xl border border-slate-700 bg-slate-950/60 p-5 text-center text-sm text-slate-400">The desk is quiet. No team has pitched yet; step forward to the first pitch.</div>}
      </div>
    </div>
  )
}
